package com.microbms.iot;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.*;

@RestController
@RequestMapping("/api/iot")
public class IoTController {
    private final JdbcTemplate db;
    public IoTController(JdbcTemplate db){this.db=db;}
    @GetMapping("/devices") public List<Map<String,Object>> devices(){return db.queryForList("SELECT id,'DEV-'||LPAD(device_no::text,3,'0') AS \"deviceCode\",device_name AS name,linked_asset AS \"linkedAsset\",location,reading_unit AS \"readingUnit\",current_reading AS \"currentReading\",alert_threshold AS \"alertThreshold\",threshold_direction AS \"thresholdDirection\",status,created_at AS \"createdAt\" FROM iot_devices ORDER BY device_no");}
    @PostMapping("/devices") public Map<String,Object> create(@RequestBody Map<String,Object>b){UUID id=UUID.randomUUID();BigDecimal reading=number(b.get("initialReading"));db.update("INSERT INTO iot_devices(id,device_name,linked_asset,location,reading_unit,current_reading,alert_threshold,threshold_direction) VALUES(?,?,?,?,?,?,?,?)",id,required(b,"name"),value(b,"linkedAsset",null),required(b,"location"),required(b,"readingUnit"),reading,number(b.get("alertThreshold")),value(b,"thresholdDirection","ABOVE"));db.update("INSERT INTO iot_readings(device_id,reading_value) VALUES(?,?)",id,reading);return db.queryForMap("SELECT id,'DEV-'||LPAD(device_no::text,3,'0') AS \"deviceCode\",device_name AS name,linked_asset AS \"linkedAsset\",location,reading_unit AS \"readingUnit\",current_reading AS \"currentReading\",alert_threshold AS \"alertThreshold\",threshold_direction AS \"thresholdDirection\",status FROM iot_devices WHERE id=?",id);}
    @PostMapping("/devices/{id}/readings") public Map<String,Object> simulate(@PathVariable UUID id,@RequestBody Map<String,Object>b){BigDecimal reading=number(b.get("reading"));Map<String,Object> device=db.queryForMap("SELECT alert_threshold AS threshold,threshold_direction AS direction,reading_unit AS unit FROM iot_devices WHERE id=?",id);BigDecimal threshold=(BigDecimal)device.get("threshold");String direction=(String)device.get("direction");boolean triggered="BELOW".equalsIgnoreCase(direction)?reading.compareTo(threshold)<0:reading.compareTo(threshold)>0;db.update("UPDATE iot_devices SET current_reading=?,updated_at=now() WHERE id=?",reading,id);db.update("INSERT INTO iot_readings(device_id,reading_value) VALUES(?,?)",id,reading);UUID alertId=null;if(triggered){alertId=UUID.randomUUID();String detail="Reading "+reading+" "+device.get("unit")+("BELOW".equalsIgnoreCase(direction)?" below ":" above ")+threshold+" "+device.get("unit");db.update("INSERT INTO iot_alerts(id,device_id,reading_value,threshold_value,alert_details) VALUES(?,?,?,?,?)",alertId,id,reading,threshold,detail);}Map<String,Object> result=new LinkedHashMap<>();result.put("deviceId",id);result.put("reading",reading);result.put("alertTriggered",triggered);result.put("alertId",alertId);return result;}
    @GetMapping("/alerts") public List<Map<String,Object>> alerts(){return db.queryForList("SELECT a.id,'DEV-'||LPAD(d.device_no::text,3,'0') AS \"deviceCode\",d.device_name AS device,a.reading_value AS reading,a.threshold_value AS threshold,a.alert_details AS details,a.status,a.work_order_reference AS \"workOrder\",a.created_at AS \"createdAt\" FROM iot_alerts a JOIN iot_devices d ON d.id=a.device_id ORDER BY a.created_at DESC");}
    @PatchMapping("/alerts/{id}/work-order") public Map<String,Object> linkWorkOrder(@PathVariable UUID id,@RequestBody Map<String,Object>b){db.update("UPDATE iot_alerts SET work_order_reference=? WHERE id=?",required(b,"workOrder"),id);return db.queryForMap("SELECT id,status,work_order_reference AS \"workOrder\" FROM iot_alerts WHERE id=?",id);}
    private static BigDecimal number(Object v){if(v==null||v.toString().isBlank())return BigDecimal.ZERO;return new BigDecimal(v.toString());}
    private static String required(Map<String,Object>b,String k){String v=value(b,k,null);if(v==null||v.isBlank())throw new IllegalArgumentException(k+" is required");return v;}
    private static String value(Map<String,Object>b,String k,String d){Object v=b.get(k);return v==null||v.toString().isBlank()?d:v.toString().trim();}
}
